import { modelVersion } from './model';
import { referenceVersion } from './references';
import type { VanatomeProbe, VanatomeVector3 } from './vendor/types';

/** Generated by scripts/compute-acupoint-depth.mjs into public/acupoint-depth.json. */
export type DepthText = { en: string; zh: string };
export type DepthLayer = {
  anatomyId: string;
  english: string;
  chinese: string;
  kind: 'muscle' | 'bone';
  entryCm: number;
  exitCm: number;
  thicknessCm: number;
  gapBeforeCm: number;
  overlapsPreviousCm: number;
  containsReference: boolean;
  normalsAgree: boolean;
  note?: DepthText;
};
export type DepthDirection = {
  terms: string[];
  en: string;
  zh: string;
  probeRelation: 'deep' | 'superficial' | 'level';
  probeRelationEn: string;
  probeRelationZh: string;
  components: Record<'superior' | 'lateral' | 'anterior' | 'deep', number>;
};
export type DepthNearby = {
  anatomyId: string;
  english: string;
  chinese: string;
  kind: 'muscle' | 'bone';
  distanceCm: number;
  overlapsReference: boolean;
  direction: DepthDirection | null;
  closestPoint: VanatomeVector3;
};
/** A published source the layer order was compared with (opened and read on `accessed`). */
export type DepthSource = { title: string; publisher: string; url: string; accessed: string; supports: DepthText };
type DepthSourceMuscleBase = { match: string; english: string; chinese: string; anatomyIds: string[] };
/** One muscle of a published layer description: on the probe (depth range) or not (closest approach of the axis). */
export type DepthSourceMuscle =
  | (DepthSourceMuscleBase & { onProbe: true; layerIds: string[]; entryCm: number; exitCm: number })
  | (DepthSourceMuscleBase & { onProbe: false; closestPartId: string; closestPartEnglish: string; distanceToProbeCm: number; atProbeDepthCm: number; direction: DepthDirection });
export type DepthSourceComparison = {
  sequence: DepthText;
  agreement: 'same-order' | 'differs';
  muscles: DepthSourceMuscle[];
  /** Muscles the probe crosses before the first bone that the description does not list. */
  modelOnlyMuscles: { anatomyId: string; english: string; chinese: string; entryCm: number; exitCm: number }[];
  notes: DepthText[];
  sources: DepthSource[];
};
export type DepthEntry = {
  pointId: string;
  side: 'right' | 'left';
  referenceAnatomyId: string;
  referencePosition: VanatomeVector3;
  axis: {
    approach: DepthText;
    rationale: DepthText;
    method: string;
    directionInward: VanatomeVector3;
    origin: VanatomeVector3;
    approachLabel: DepthText;
    angleFromNominalDeg: number;
    angleToEntrySurfaceNormalDeg: number;
    probeStartCm: number;
    probeEndCm: number;
    layerStopReason: string;
    sensitivity: { patchRadiiCm: number[]; referenceDepthCm: { min: number; max: number }; layerSequences: string[]; sameLayerSequence: boolean };
    firstBoneSurface?: { anatomyId: string; angleToSurfaceNormalDeg: number };
  };
  referenceDepthCm: number;
  referenceLayer: { anatomyId: string; english: string; chinese: string } | null;
  layers: DepthLayer[];
  alsoInsideReference: string[];
  nearby: DepthNearby[];
  notModeled: { english: string; chinese: string; note: DepthText }[];
  /** Present for points whose layer order was compared with published descriptions (SI11, SI12, SI9). */
  sourceComparison?: DepthSourceComparison | null;
  limitations: DepthText[];
};
export type DepthData = {
  schemaVersion: 1;
  modelVersion: string;
  referenceVersion: string;
  generatedBy: string;
  scope: DepthText;
  points: Record<string, DepthEntry>;
};

export async function loadAcupointDepth(): Promise<DepthData> {
  const res = await fetch('./acupoint-depth.json');
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const data = await res.json() as DepthData;
  if (data.schemaVersion !== 1) throw new Error('Unsupported depth data version / 深浅数据版本不符');
  if (data.modelVersion !== modelVersion || data.referenceVersion !== referenceVersion) throw new Error('Depth data belong to another model or reference version / 深浅数据与当前模型或参照版本不一致');
  return data;
}

const structureColors: Record<string, string> = {
  'deltoid-muscles-acromial-part-of-deltoid-muscle': '#e39270',
  'deltoid-muscles-scapular-spinal-part-of-deltoid-muscle': '#cf7c63',
  'deltoid-muscles-clavicular-part-of-deltoid-muscle': '#eeaa86',
  'rotator-cuff-muscles-supraspinatus-muscle': '#7db7e8',
  'rotator-cuff-muscles-infraspinatus-muscle': '#6ccaa4',
  'rotator-cuff-muscles-teres-minor-muscle': '#b69be3',
  'rotator-cuff-muscles-subscapularis-muscle': '#e6a2c6',
  // Shoulder add-on muscles that appear on the probes or among nearby structures.
  'trapezius-muscles-descending-part-of-trapezius-muscle': '#b8566c',
  'trapezius-muscles-transverse-part-of-trapezius-muscle': '#c9637a',
  'trapezius-muscles-ascending-part-of-trapezius-muscle': '#d9707f',
  'serratus-anterior-muscles-serratus-anterior-muscle': '#b5c95f',
  'triceps-brachii-muscles-long-head-of-triceps-brachii': '#62c3d6',
  'teres-major-muscles-teres-major-muscle': '#8c9de6',
  'latissimus-dorsi-muscles-latissimus-dorsi-muscle': '#7fb39a',
  'levator-scapulae-muscles-levator-scapulae': '#c49ad6',
  'biceps-brachii-muscles-long-head-of-biceps-brachii': '#e3b25a',
  'appendicular-skeleton-scapula': '#eadba8',
  'appendicular-skeleton-humerus': '#dccb92',
  'appendicular-skeleton-clavicle': '#efe2bb',
};
export function structureColor(anatomyId: string, kind: 'muscle' | 'bone') {
  const base = anatomyId.replace(/-(right|left)$/, '');
  return structureColors[base] ?? (kind === 'bone' ? '#cfc5a2' : '#9fbfae');
}

/** Depths are rounded to 0.1 cm for reading; the model is not more precise than that. */
export const formatCm = (value: number) => (value > 0 && value < 0.05 ? '<0.1' : value.toFixed(1));

export const pointAtDepth = (entry: DepthEntry, depthCm: number): VanatomeVector3 => {
  const { origin, directionInward: d } = entry.axis;
  return [origin[0] + d[0] * depthCm / 100, origin[1] + d[1] * depthCm / 100, origin[2] + d[2] * depthCm / 100];
};

/** Layers worth a 3D callout: the reference's own layer first, then the others in depth order (max 4). */
function calloutLayers(entry: DepthEntry) {
  const own = entry.layers.find(layer => layer.anatomyId === entry.referenceAnatomyId);
  const others = entry.layers.filter(layer => layer !== own && layer.thicknessCm >= 0.2);
  return [...(own ? [own] : []), ...others].slice(0, 4).sort((a, b) => a.entryCm - b.entryCm);
}

export function depthProbe(entry: DepthEntry, markerColor: string, showChinese: boolean, customized = false): VanatomeProbe {
  const end = entry.axis.probeEndCm;
  const visible = (layer: DepthLayer) => [layer.entryCm, Math.min(layer.exitCm, end - 0.15)] as const;
  const ticks: VanatomeVector3[] = [];
  const seen: number[] = [];
  for (const layer of entry.layers) for (const depth of [layer.entryCm, layer.exitCm]) {
    if (depth > end - 0.1 || seen.some(d => Math.abs(d - depth) < 0.06)) continue;
    seen.push(depth);
    ticks.push(pointAtDepth(entry, depth));
  }
  return {
    id: `depth:${entry.pointId}-${entry.side}`,
    start: pointAtDepth(entry, entry.axis.probeStartCm),
    end: pointAtDepth(entry, end),
    dashedUntil: pointAtDepth(entry, 0),
    // Where source meshes overlap, the reference's own structure is drawn last (on top).
    segments: [...entry.layers].sort((a, b) => Number(a.anatomyId === entry.referenceAnatomyId) - Number(b.anatomyId === entry.referenceAnatomyId)).map(layer => {
      const [from, to] = visible(layer);
      return { start: pointAtDepth(entry, from), end: pointAtDepth(entry, to), color: structureColor(layer.anatomyId, layer.kind) };
    }),
    ticks,
    marker: { position: entry.referencePosition, color: markerColor },
    callouts: [
      ...calloutLayers(entry).map(layer => {
        const [from, to] = visible(layer);
        return {
          id: layer.anatomyId,
          label: `${layer.english} ${formatCm(layer.entryCm)}–${formatCm(layer.exitCm)} cm${showChinese && layer.chinese ? `\n${layer.chinese}` : ''}`,
          position: pointAtDepth(entry, (from + to) / 2),
          color: structureColor(layer.anatomyId, layer.kind),
        };
      }),
      { id: 'reference', label: `● ${customized ? 'Built-in reference' : 'Reference'} ${formatCm(entry.referenceDepthCm)} cm${showChinese ? (customized ? ' · 内置参照点' : ' · 参照点') : ''}`, position: entry.referencePosition, color: markerColor, emphasis: true },
    ],
  };
}
